// Узел «Смещение»: с какого обновления Телеграма читать, чтобы не ответить дважды.
// src/settings.js (вклеено scripts/build-workflows.js, править в src/)
const settingsLib = (() => {
  const module = { exports: {} };
// Настройки, которые меняются из бота без правки конвейера: порог оценки, смещение обновлений Телеграма.
'use strict';

const SCHEMA = `CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);`;

function createSettings(db) {
  function init() {
    db.exec(SCHEMA);
  }
  function get(key, fallback = null) {
    const r = db.prepare('SELECT value FROM settings WHERE key = ?').get(key);
    return r ? r.value : fallback;
  }
  function getNumber(key, fallback) {
    const n = Number(get(key, null));
    return get(key, null) !== null && Number.isFinite(n) ? n : fallback;
  }
  function set(key, value) {
    db.prepare('INSERT INTO settings (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value').run(
      key,
      String(value)
    );
  }
  return { init, get, getNumber, set };
}

// Порог: из бота, если там задан, иначе из узла «Настройки».
function minScoreOf(settings, fallback) {
  const n = settings.getNumber('min_score', Number(fallback ?? 7));
  return Number.isFinite(n) ? n : 7;
}

if (typeof module !== 'undefined') {
  module.exports = { SCHEMA, createSettings, minScoreOf };
}
  return module.exports;
})();
// src/db.js (вклеено scripts/build-workflows.js, править в src/)
const dbLib = (() => {
  const module = { exports: {} };
// Открытие общей базы SQLite. В неё пишут оба конвейера (сбор и бот), иногда одновременно,
// поэтому база ждёт освобождения до 5 секунд вместо ошибки «database is locked».
'use strict';

function openDb(DatabaseSync, path) {
  const db = new DatabaseSync(path);
  db.exec('PRAGMA busy_timeout = 5000');
  try {
    db.exec('PRAGMA journal_mode = WAL');
  } catch {}
  return db;
}

if (typeof module !== 'undefined') {
  module.exports = { openDb };
}
  return module.exports;
})();

const { DatabaseSync } = require('node:sqlite');
const db = dbLib.openDb(DatabaseSync, $('Настройки бота').first().json.JR_DB_PATH);
try {
  const store = settingsLib.createSettings(db);
  store.init();
  return [{ json: { offset: Number(store.get('tg_offset', '0')) || 0 } }];
} finally {
  db.close();
}

// Узел «Команды»: обновления Телеграма -> ответы бота. Каждый ответ уходит узлом «Ответы».
// src/text.js (вклеено scripts/build-workflows.js, править в src/)
const textLib = (() => {
  const module = { exports: {} };
// Общие функции для текста: разбор сущностей HTML, очистка от тегов, сравнение строк.
// Файл без зависимостей: подходит для вклейки в узел Code n8n.
'use strict';

const NAMED = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', laquo: '«', raquo: '»', mdash: '-', ndash: '-', hellip: '…' };

function decodeEntities(s) {
  return String(s ?? '').replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (m, e) => {
    if (e[0] === '#') {
      const code = e[1] === 'x' || e[1] === 'X' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10);
      return Number.isFinite(code) && code > 0 && code < 0x110000 ? String.fromCodePoint(code) : m;
    }
    const v = NAMED[e.toLowerCase()];
    return v === undefined ? m : v;
  });
}

// HTML в обычный текст: <br> и концы абзацев становятся переносами строк.
function htmlToText(html) {
  const s = String(html ?? '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|li|h\d)>/gi, '\n')
    .replace(/<[^>]*>/g, '');
  return decodeEntities(s)
    .replace(/[ \t\u00a0]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

// Нижний регистр, ё -> е, только буквы и цифры через пробел.
function normalizeText(s) {
  return String(s || '')
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .trim();
}

function tokens(s) {
  const t = normalizeText(s);
  return t ? t.split(' ') : [];
}

// Первая непустая строка без эмодзи и значков по краям, не длиннее max знаков.
function firstLine(text, max = 120) {
  const line = String(text || '')
    .split('\n')
    .map((l) => l.replace(/^[^\p{L}\p{N}]+|[\s:,;\-]+$/gu, '').trim())
    .find(Boolean);
  if (!line) return '';
  return line.length > max ? line.slice(0, max - 1).replace(/\s+\S*$/, '') + '…' : line;
}

if (typeof module !== 'undefined') {
  module.exports = { decodeEntities, htmlToText, normalizeText, tokens, firstLine };
}
  return module.exports;
})();
// src/message.js (вклеено scripts/build-workflows.js, править в src/)
const messageLib = (() => {
  const module = { exports: {} };
// Подборка вакансий для Телеграма с разметкой HTML. Длинная подборка делится
// на несколько сообщений по границам вакансий.
'use strict';

const TELEGRAM_TEXT_LIMIT = 4096;

function escapeHtml(s) {
  return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const escapeAttr = (s) => escapeHtml(s).replace(/"/g, '&quot;');

function formatVacancy(v) {
  const head = `<b>${escapeHtml(v.title)}</b>` + (v.company ? ` · ${escapeHtml(v.company)}` : '');
  const meta = [v.salary, v.format].filter(Boolean).map(escapeHtml).join(' · ');
  const why = `${v.score}/10` + (v.reason ? `: ${escapeHtml(v.reason)}` : '');
  const link = `<a href="${escapeAttr(v.link)}">${escapeHtml(v.source || 'открыть')}</a>`;
  return [head, meta, why, link].filter(Boolean).join('\n');
}

// vacancies: [{ title, company, salary, format, score, reason, link, source }].
// Возвращает массив текстов сообщений; пустой, если вакансий нет.
// Лимит считается по длине с тегами: это строже, чем считает Телеграм.
function buildDigest(vacancies, options = {}) {
  const limit = options.limit ?? TELEGRAM_TEXT_LIMIT;
  const list = [...(vacancies || [])].sort((a, b) => b.score - a.score);
  if (!list.length) return [];
  const header = `Подходящие вакансии: ${list.length}`;
  const messages = [];
  let cur = header;
  for (const v of list) {
    const block = formatVacancy(v);
    if (block.length + 2 > limit) throw new Error('вакансия не помещается в сообщение');
    if (cur.length + 2 + block.length > limit) {
      messages.push(cur);
      cur = block;
    } else {
      cur += '\n\n' + block;
    }
  }
  messages.push(cur);
  return messages;
}

// Отдельное сообщение на вакансию: карточка и под ней сопроводительное письмо
// блоком кода, его можно скопировать одним нажатием. Длинное письмо укорачивается
// так, чтобы сообщение влезло в лимит Телеграма.
function formatCard(v, options = {}) {
  const limit = options.limit ?? TELEGRAM_TEXT_LIMIT;
  const card = formatVacancy(v);
  const letter = String(v.letter || '').trim();
  if (!letter) return card;
  const head = card + '\n\nСопроводительное письмо:\n<pre>';
  const tail = '</pre>';
  let body = escapeHtml(letter);
  const room = limit - head.length - tail.length;
  if (room < 50) return card;
  if (body.length > room) body = body.slice(0, room - 1).replace(/&[a-z]*$/i, '') + '…';
  return head + body + tail;
}

// Сначала лучшие: если вакансий за раз несколько, сверху придёт самая подходящая.
function buildCards(vacancies, options = {}) {
  return [...(vacancies || [])].sort((a, b) => b.score - a.score).map((v) => formatCard(v, options));
}

if (typeof module !== 'undefined') {
  module.exports = { TELEGRAM_TEXT_LIMIT, escapeHtml, formatVacancy, buildDigest, formatCard, buildCards };
}
  return module.exports;
})();
// src/filter.js (вклеено scripts/build-workflows.js, править в src/)
const filterLib = (() => {
  const module = { exports: {} };
// Отбор вакансий перед нейросетью: свежесть, ключевые слова, стоп-слова в заголовке,
// отсев повторов по ссылке и по похожему тексту (одна вакансия в разных каналах).
'use strict';

const { normalizeText, tokens } = typeof textLib !== 'undefined' ? textLib : require('./text.js');

const TRACKING = /^(utm_\w+|fbclid|gclid|yclid|ref|from|hhtmFrom\w*|query)$/i;

// Одна вакансия по разным ссылкам: без схемы, www, якоря, меток и конечной косой черты.
// Разбор вручную: в песочнице узла Code n8n нет URL и URLSearchParams.
function normalizeUrl(url) {
  const raw = String(url || '').trim();
  if (!raw) return '';
  const m = raw.match(/^[a-z][a-z0-9+.-]*:\/\/([^\/?#]+)([^?#]*)(?:\?([^#]*))?/i);
  if (!m) return raw.toLowerCase();
  const host = m[1].toLowerCase().replace(/^www\./, '').replace(/:(80|443)$/, '');
  const params = (m[3] || '')
    .split('&')
    .filter(Boolean)
    .map((p) => {
      const i = p.indexOf('=');
      return i < 0 ? [p, ''] : [p.slice(0, i), p.slice(i + 1)];
    })
    .filter(([k]) => !TRACKING.test(k))
    .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
  const query = params.length ? '?' + params.map(([k, v]) => `${k}=${v}`).join('&') : '';
  return host + m[2].replace(/\/+$/, '') + query;
}

// Слово ищется как начало слова в тексте («стажировк» найдёт «стажировка»),
// фраза как подряд идущие слова. Слова до трёх букв только целиком («ии», «ml»).
function keywordMatches(textTokens, keyword) {
  const kw = tokens(keyword);
  if (!kw.length) return false;
  for (let i = 0; i + kw.length <= textTokens.length; i++) {
    let ok = true;
    for (let j = 0; j < kw.length; j++) {
      const t = textTokens[i + j];
      const k = kw[j];
      if (k.length <= 3 ? t !== k : !t.startsWith(k)) {
        ok = false;
        break;
      }
    }
    if (ok) return true;
  }
  return false;
}

function findKeywords(text, keywords) {
  const tt = tokens(text);
  return (keywords || []).filter((k) => keywordMatches(tt, k));
}

// Сколько лет опыта требует вакансия: наибольшее число из фраз вроде «опыт от 3 лет»,
// «опыт работы не менее 2 лет», «3+ года», «Опыт, лет: 2». null, если не указано.
const EXPERIENCE = [
  /опыт[а-я]*,?\s*(?:работы\s*)?(?:коммерческой\s*)?(?:разработки\s*)?(?:лет:?\s*)?(?:от|не\s*менее|более|свыше|больше|>=?)?\s*(\d+(?:[.,]\d+)?)\s*\+?\s*(?:лет|года?|г\.|-?х)?/gi,
  /(?:от|не\s*менее|более|свыше)\s*(\d+(?:[.,]\d+)?)\s*(?:лет|года?)\s*(?:коммерческого\s*|подтвержд[а-я]*\s*|практического\s*)?опыт/gi,
  /(\d+(?:[.,]\d+)?)\s*\+\s*(?:лет|года?|years?)/gi,
  /(\d+(?:[.,]\d+)?)\s*\+?\s*years?\s*(?:of\s*)?(?:commercial\s*|professional\s*)?experience/gi,
];

function requiredExperience(text) {
  const s = String(text || '').replace(/ё/gi, 'е');
  let max = null;
  for (const re of EXPERIENCE) {
    for (const m of s.matchAll(re)) {
      const n = Number(m[1].replace(',', '.'));
      if (Number.isFinite(n) && n <= 15 && (max === null || n > max)) max = n;
    }
  }
  return max;
}

// Отпечаток для сравнения: заголовок и начало текста.
function fingerprint(item) {
  return `${(item && item.title) || ''} ${String((item && item.text) || '').slice(0, 300)}`;
}

// Коэффициент Жаккара по основам слов (первые 5 букв), короткие слова не считаются.
function similarity(a, b) {
  const stems = (s) => new Set(tokens(s).filter((t) => t.length > 2).map((t) => t.slice(0, 5)));
  const A = stems(a);
  const B = stems(b);
  if (A.size < 3 || B.size < 3) return 0;
  let inter = 0;
  for (const x of A) if (B.has(x)) inter++;
  return inter / (A.size + B.size - inter);
}

// items: [{ title, link, text, date, source }]. seen: недавние записи журнала { link, title, text }.
// Возвращает принятые и отклонённые с причиной. options.now для проверки свежести.
function filterVacancies(items, config = {}, seen = [], options = {}) {
  const keywords = config.keywords || [];
  const exclude = config.excludeTitle || [];
  const threshold = config.similarityThreshold ?? 0.8;
  const maxAge = (config.maxAgeDays ?? 4) * 86400000;
  const now = Date.parse(options.now || new Date().toISOString());

  const accepted = [];
  const rejected = [];
  const seenUrls = new Set(seen.map((s) => normalizeUrl(s.link)).filter(Boolean));
  const seenPrints = seen.map(fingerprint);

  for (const item of items || []) {
    const reject = (reason, extra = {}) => rejected.push({ ...item, reason, ...extra });
    const title = String((item && item.title) || '').trim();
    if (!title || !item.link) {
      reject('нет заголовка или ссылки');
      continue;
    }
    const url = normalizeUrl(item.link);
    if (seenUrls.has(url)) {
      reject('повтор ссылки');
      continue;
    }
    seenUrls.add(url);
    const t = Date.parse(item.date);
    if (Number.isFinite(t) && now - t > maxAge) {
      reject('старое объявление');
      continue;
    }
    const bad = findKeywords(title, exclude);
    if (bad.length) {
      reject('стоп-слово в заголовке', { matched: bad });
      continue;
    }
    const years = config.maxExperienceYears != null ? requiredExperience(`${title}\n${item.text || ''}`) : null;
    if (years !== null && years > config.maxExperienceYears) {
      reject('требуется большой опыт', { years });
      continue;
    }
    const matched = findKeywords(`${title} ${item.text || ''}`, keywords);
    // Вакансии из писем уже отобраны сохранённым поиском на сайте, а в письме
    // от них только заголовок и пара строк: ключевые слова там часто не видны.
    if (keywords.length && !matched.length && !item.fromMail) {
      reject('нет ключевых слов');
      continue;
    }
    const print = fingerprint(item);
    let dup = null;
    for (const p of seenPrints) {
      const sim = similarity(print, p);
      if (sim >= threshold) {
        dup = Math.round(sim * 100) / 100;
        break;
      }
    }
    if (dup !== null) {
      reject('похожая вакансия уже была', { similarity: dup });
      continue;
    }
    seenPrints.push(print);
    accepted.push({ ...item, matched });
  }
  return { accepted, rejected };
}

if (typeof module !== 'undefined') {
  module.exports = { normalizeUrl, findKeywords, similarity, filterVacancies, requiredExperience };
}
  return module.exports;
})();
// src/journal.js (вклеено scripts/build-workflows.js, править в src/)
const journalLib = (() => {
  const module = { exports: {} };
// Журнал в SQLite: что собрано, что отсеяно и почему, что ушло в подборку.
// Принимает любую базу с exec(sql) и prepare(sql) (node:sqlite или better-sqlite3).
'use strict';

const STATUSES = ['collected', 'rejected', 'matched'];

const SCHEMA = `
CREATE TABLE IF NOT EXISTS vacancies (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  url_key TEXT NOT NULL UNIQUE,
  link TEXT NOT NULL,
  title TEXT NOT NULL,
  snippet TEXT,
  source TEXT,
  status TEXT NOT NULL CHECK (status IN ('collected', 'rejected', 'matched')),
  reason TEXT,
  score REAL,
  collected_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS vacancies_status ON vacancies (status);
CREATE INDEX IF NOT EXISTS vacancies_collected_at ON vacancies (collected_at);
`;

// Поля из ответа нейросети. Добавлены позже, поэтому в старых базах создаются в init.
const EXTRA = { why: 'TEXT', company: 'TEXT', salary: 'TEXT', format: 'TEXT', letter: 'TEXT', shown: 'INTEGER DEFAULT 0' };

function createJournal(db, options = {}) {
  if (!db || typeof db.exec !== 'function' || typeof db.prepare !== 'function') {
    throw new TypeError('нужен объект базы с exec и prepare');
  }
  const now = options.now || (() => new Date().toISOString());
  const normalizeUrl = options.normalizeUrl || ((u) => String(u || '').trim().toLowerCase());
  const keyOf = (link) => {
    const key = normalizeUrl(link);
    if (!key) throw new Error('нет ссылки');
    return key;
  };
  const get = (key) => db.prepare('SELECT * FROM vacancies WHERE url_key = ?').get(key) || null;

  function init() {
    db.exec(SCHEMA);
    const have = new Set(db.prepare('PRAGMA table_info(vacancies)').all().map((c) => c.name));
    for (const [name, type] of Object.entries(EXTRA)) {
      if (!have.has(name)) db.exec(`ALTER TABLE vacancies ADD COLUMN ${name} ${type}`);
    }
  }

  // Новая запись или уже известная ссылка: тогда { added: false } и прежняя запись.
  function collected(item) {
    const title = String((item && item.title) || '').trim();
    if (!title) throw new Error('нет заголовка');
    const key = keyOf(item.link);
    const old = get(key);
    if (old) return { added: false, item: old };
    const t = now();
    db.prepare(
      `INSERT INTO vacancies (url_key, link, title, snippet, source, status, collected_at, updated_at)
       VALUES (?, ?, ?, ?, ?, 'collected', ?, ?)`
    ).run(key, String(item.link).trim(), title, String(item.text || '').slice(0, 300), item.source || null, t, t);
    return { added: true, item: get(key) };
  }

  // fields: поля из ответа нейросети { reason, company, salary, format, letter, title }.
  function finish(link, status, reason, score, fields = null, shown = 0) {
    const key = keyOf(link);
    const old = get(key);
    if (!old) throw new Error(`нет в журнале: ${link}`);
    if (old.status !== 'collected') throw new Error(`запись уже закрыта: ${old.status}`);
    const f = fields || {};
    const opt = (v) => (v === undefined || v === null || v === '' ? null : String(v));
    db.prepare(
      `UPDATE vacancies SET status = ?, reason = ?, score = ?, why = ?, company = ?, salary = ?, format = ?,
       letter = ?, title = COALESCE(?, title), shown = ?, updated_at = ? WHERE url_key = ?`
    ).run(status, reason ?? null, score ?? null, opt(f.reason), opt(f.company), opt(f.salary), opt(f.format),
      opt(f.letter), opt(f.title), shown, now(), key);
    return get(key);
  }

  // У отказа всегда есть причина: по журналу видно, почему вакансия не пришла.
  function rejected(link, reason, score, fields) {
    const r = String(reason || '').trim();
    if (!r) throw new Error('у отказа должна быть причина');
    return finish(link, 'rejected', r, score, fields);
  }

  // Подходящая вакансия сразу уходит в Телеграм, поэтому отмечается показанной.
  function matched(link, score, reason, fields) {
    if (typeof score !== 'number' || !Number.isFinite(score)) throw new Error('нет оценки');
    return finish(link, 'matched', reason, score, fields, 1);
  }

  const since = (days) => new Date(Date.parse(now()) - days * 86400000).toISOString();

  // Оценённые нейросетью, но ниже порога и ещё не показанные: { from, to, days, limit }.
  // to не входит в отрезок: это текущий порог.
  function below({ from = 0, to = 11, days = 7, limit = 10 } = {}) {
    return db
      .prepare(
        `SELECT * FROM vacancies WHERE status = 'rejected' AND score IS NOT NULL AND score >= ? AND score < ?
         AND shown = 0 AND reason LIKE 'ниже порога%' AND collected_at >= ? ORDER BY score DESC, id DESC LIMIT ?`
      )
      .all(from, to, since(days), limit);
  }

  function markShown(ids) {
    const st = db.prepare('UPDATE vacancies SET shown = 1 WHERE id = ?');
    for (const id of ids || []) st.run(id);
  }

  // Подходящие за последние hours часов, свежие сверху.
  function recentMatched(hours = 24, limit = 5) {
    return db
      .prepare(`SELECT * FROM vacancies WHERE status = 'matched' AND updated_at >= ? ORDER BY id DESC LIMIT ?`)
      .all(since(hours / 24), limit);
  }

  // Счётчики начиная с момента fromIso: собрано, оценено нейросетью, подошло, ниже порога, отсеяно фильтром.
  function counts(fromIso) {
    const r = db
      .prepare(
        `SELECT COUNT(*) AS collected,
           SUM(CASE WHEN score IS NOT NULL THEN 1 ELSE 0 END) AS analyzed,
           SUM(CASE WHEN status = 'matched' THEN 1 ELSE 0 END) AS matched,
           SUM(CASE WHEN status = 'rejected' AND reason LIKE 'ниже порога%' THEN 1 ELSE 0 END) AS below,
           SUM(CASE WHEN status = 'rejected' AND score IS NULL THEN 1 ELSE 0 END) AS filtered
         FROM vacancies WHERE collected_at >= ?`
      )
      .get(fromIso || '0000');
    const n = (v) => Number(v || 0);
    return { collected: n(r.collected), analyzed: n(r.analyzed), matched: n(r.matched), below: n(r.below), filtered: n(r.filtered) };
  }

  // Убрать ещё не закрытую запись: вакансия снова придёт в следующий запуск.
  // Нужно, когда нейросеть не ответила, чтобы вакансия не пропала.
  function forget(link) {
    const key = keyOf(link);
    const old = get(key);
    if (!old) return false;
